$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$path=Join-Path $root 'src\collect-corrected-route-preflight.ps1';if(-not(Test-Path $path)){throw 'collector missing'};$text=Get-Content $path -Raw
